Method.Source:
    /// <summary>
    /// Find wave line
    /// </summary>
    /// <param name = "_waveId">wave Id</param>
    /// <param name = "_documentNumber">order number</param>
    /// <param name = "_lineNum">linenumber</param>
    /// <param name = "_update">update table</param>
    /// <returns>METWaveLine</returns>
    static METWaveLine find(METWaveId       _waveId,
                            METDocumentNum  _documentNumber,
                            LineNum         _lineNum,
                            boolean         _update      = false)
    {
        METWaveLine waveLine;

        if (_waveId)
        {
            if (_update)
            {
                waveLine.selectForUpdate(_update);
            }

            select firstonly waveLine
                index hint WaveLineIdx
                where waveLine.WaveId  == _waveId
                && waveLine.DocumentNumber  == _documentNumber
                &&  waveLine.LineNumber  == _lineNum;
        }

        return waveLine;
    }

    /// <summary>
    /// find by the source line recId
    /// </summary>
    /// <param name = "_refRecId">source line recid</param>
    /// <param name = "_update">update buffer</param>
    /// <returns>METWaveLine</returns>
    static METWaveLine findByDocumentRefRecId(RefRecId       _refRecId,
                                              boolean         _update      = false)
    {
        METWaveLine waveLine;

        if (_refRecId)
        {
            if (_update)
            {
                waveLine.selectForUpdate(_update);
            }

            select firstonly waveLine
                index hint DocNumRefRecIdIdx
                where waveLine.DocNumRefRecId  == _refRecId;
                
        }

        return waveLine;
    }

    /// <summary>
    /// Check if record exists
    /// </summary>
    /// <param name = "_waveId">wave Id</param>
    /// <param name = "_documentNumber">Order number</param>
    /// <param name = "_lineNum">Line Number</param>
    /// <returns>true or false</returns>
    static boolean exist(METWaveId _waveId,
                         METDocumentNum  _documentNumber,
                         LineNum  _lineNum)
    {
        if (!_waveId || _documentNumber || _lineNum)
        {
            return false;
        }

        return (select firstonly RecId from METWaveLine
                    index hint WaveLineIdx
                    where metWaveLine.WaveId   == _waveId
                    && metWaveLine.DocumentNumber  == _documentNumber
                    && metWaveLine.LineNumber  == _lineNum).RecId != 0;
    }

    /// <summary>
    /// Find by source order number
    /// </summary>
    /// <param name = "_documentNumber">Order number</param>
    /// <returns>METWaveLine</returns>
    static METWaveLine findByDocumentNumber(METDocumentNum  _documentNumber)
    {
        METWaveLine  waveLine;

        if (_documentNumber)
        {
            select firstonly waveLine
                where waveLine.DocumentNumber == _documentNumber;
        }

        return waveLine;
    }
